macros.exemplo:
// La feuille de calcul est `sheet`. Ctrl+Enter exécute ; Ctrl+Z annule toute la macro.
// Toutes les fonctions, avec des exemples : bouton "Guide".

// 1) Lire et écrire
sheet.set("F1", "Rapport");
sheet.log("A1 vaut :", sheet.value("A1"));

// 2) Travailler avec une plage
sheet.range("A1:D1").style({ bold: true });

// 3) Remplir avec une boucle
for (let row = 2; row <= 6; row++) {
  sheet.set("F" + row, "=D" + row + "*0.1");
}

// 4) Créer une fonction à utiliser dans les cellules : =TAXE(D2)
sheet.defineFunction("TAXE", (value) => value * 0.15);

